package com.jayaseelan.nexoramart.controller;
import com.jayaseelan.nexoramart.dao.JdbcProductDAO; import com.jayaseelan.nexoramart.model.Product; import com.jayaseelan.nexoramart.service.ProductService; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import javax.sql.DataSource; import java.io.IOException; import java.math.BigDecimal;
@WebServlet("/seller/products") public class SellerProductServlet extends HttpServlet{private ProductService s;public void init(){s=new ProductService(new JdbcProductDAO((DataSource)getServletContext().getAttribute("dataSource")));}private Long seller(HttpServletRequest r,HttpServletResponse p)throws IOException{HttpSession x=r.getSession(false);Object id=x==null?null:x.getAttribute("userId");Object role=x==null?null:x.getAttribute("userRole");if(id==null||!"SELLER".equals(role)){p.sendRedirect(r.getContextPath()+"/login");return null;}return(Long)id;}protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{Long id=seller(r,p);if(id==null)return;try{r.setAttribute("products",s.seller(id));r.getRequestDispatcher("/WEB-INF/views/seller/products.jsp").forward(r,p);}catch(Exception e){r.setAttribute("error","Unable to load your products.");r.getRequestDispatcher("/WEB-INF/views/seller/products.jsp").forward(r,p);}}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{Long id=seller(r,p);if(id==null)return;try{String a=r.getParameter("action");if("add".equals(a)){Product x=form(r);x.setSellerId(id);s.create(x);}else if("update".equals(a)){Product x=form(r);x.setId(Long.parseLong(r.getParameter("id")));s.update(x,id);}else if("delete".equals(a)){s.delete(Long.parseLong(r.getParameter("id")),id);}else{p.sendError(400);return;}p.sendRedirect(r.getContextPath()+"/seller/products");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,p);}}private Product form(HttpServletRequest r){Product p=new Product();p.setName(r.getParameter("name"));p.setBrand(r.getParameter("brand"));p.setModel(r.getParameter("model"));p.setDescription(r.getParameter("description"));p.setCategory(r.getParameter("category"));p.setPrice(new BigDecimal(r.getParameter("price")));p.setStockQty(Integer.parseInt(r.getParameter("stockQty")));p.setRam(r.getParameter("ram"));p.setStorage(r.getParameter("storage"));p.setDisplaySize(r.getParameter("displaySize"));p.setCamera(r.getParameter("camera"));p.setBattery(r.getParameter("battery"));p.setImageUrl1(r.getParameter("imageUrl1"));p.setImageUrl2(r.getParameter("imageUrl2"));p.setImageUrl3(r.getParameter("imageUrl3"));return p;}}
